export function makeStock(initial) {
  let values = structuredClone(initial);
  return {
    read: (tenant, sku) => {
      if (!Object.hasOwn(values, tenant)) return undefined;
      const inventory = values[tenant];
      return inventory != null && Object.hasOwn(inventory, sku) ? inventory[sku] : undefined;
    },
    current: () => values,
    publish: next => { values = next; },
  };
}

